{
  "packet_id": "H6-T01-3",
  "claim_id": "C057",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C057.component",
    "value": "The trial should be stopped or revised if it compromises essential crew access.",
    "scope": "A conditional operational stopping rule; what counts as essential access is unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P034 explicitly makes compromised essential crew access a trigger for stopping or revising the trial."
    }
  },
  "signal_basis": {
    "component_id": "C057.signal_basis",
    "value": "Monitor completed or displaced bookings during the trial, assess access effects against specified acceptable limits, and stop or revise if essential crew access is compromised.",
    "scope": "Access effects of the selected trial; displacement alone does not establish compromised essential access.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P033",
          "role": "SUPPORT"
        },
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply trial monitoring, specification of acceptable access effects, and the essential-access stopping condition."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C057.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this supported operational stopping rule."
    }
  },
  "rationale": "Given that the trial compromises essential crew access, stopping or revising it follows from the mapping's explicit operational constraint. The claim does not infer a cause of lateness or promise improvement.",
  "uncertainty": "Essential access is not defined. This limits application to particular observations but does not undermine the rule when its triggering condition is assumed satisfied.",
  "anomalies": []
}
